examples.template:
MonarchDeviceFrame(
    label = {{label}},
    screenSize = DpSize({{width}}.dp, {{height}}.dp),
    statusBarTime = {{statusBarTime}},
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = MonarchTheme.spacing.space4, vertical = MonarchTheme.spacing.space6),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    ) {
        MonarchAvatar(image = null, name = {{name}}, size = MonarchAvatarSize.Lg)
        MonarchText(text = {{name}}, style = MonarchTextStyle.BodyStrong)
        MonarchText(text = {{tagline}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        MonarchButton(text = {{links.0}}, onClick = {}, modifier = Modifier.fillMaxWidth())
        MonarchButton(text = {{links.1}}, onClick = {}, modifier = Modifier.fillMaxWidth())
        MonarchButton(text = {{links.2}}, onClick = {}, modifier = Modifier.fillMaxWidth())
    }
}

